/usr/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>FIELD NOTES</title>
<style>
:root{--paper:#f6f3eb;--ink:#163b43;--accent:#bf4e2e;--radius:0px;--font:system-ui}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:18px var(--font)}header,section{padding:32px}a,button{border-radius:var(--radius);font-family:var(--font)}.cta{display:inline-block;background:var(--ink);color:var(--paper);padding:16px}a:focus-visible{outline:3px solid var(--accent);outline-offset:4px}

/* Keep the supplied palette, typography and control rules authoritative. */
body{line-height:1.5}
header,main{max-width:1600px;margin-inline:auto}
header{display:flex;align-items:center;gap:clamp(20px,3vw,48px);padding-block:28px;border-bottom:1px solid var(--ink);margin-inline:32px;padding-inline:0}
header span{margin-right:auto;font-size:16px;font-weight:750;letter-spacing:.13em}
header a{font-size:14px;text-underline-offset:5px}
section{padding-block:64px}
#intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:clamp(32px,5vw,80px);align-items:center}
.intro-copy{padding-block:24px}
.eyebrow{margin:0 0 36px;font-size:12px;letter-spacing:.16em;font-weight:650;display:flex;align-items:center;gap:12px}
.eyebrow::before{content:"";width:24px;height:2px;background:var(--accent);flex:none}
h1{font-size:clamp(52px,6.4vw,100px);font-weight:550;letter-spacing:-.065em;line-height:1.02;margin:0 0 32px;max-width:9.5em;text-wrap:balance}
.intro-description{max-width:28ch;margin:0 0 32px;font-size:clamp(18px,1.6vw,23px);line-height:1.5}
/* Retain the CTA'"'s original font size, padding, colors and square corners. */
.cta{line-height:normal}
.hero-media{position:relative;isolation:isolate;align-self:stretch;min-height:560px;background:var(--ink);overflow:hidden}
.hero-media::before,.hero-media::after{content:\"\";position:absolute;z-index:1;inset:0 0 auto;height:20px;background:var(--ink);pointer-events:none}
.hero-media::after{inset:auto 0 0}
.hero-media video{display:block;width:100%;height:100%;position:absolute;inset:0;object-fit:cover;object-position:60% center}
/* Keep native transport controls clear of the decorative frame. */
.hero-media::after{display:none}
#work{border-top:1px solid var(--ink);margin:16px 32px 0;padding-inline:0;padding-block:48px 80px}
h2{font-size:clamp(32px,3.5vw,54px);letter-spacing:-.045em;font-weight:550;line-height:1.1;margin:0 0 36px}
.work-layout{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(0,1fr);gap:clamp(32px,6vw,96px);align-items:center}
.work-image{margin:0;overflow:hidden;background:var(--ink);aspect-ratio:2.1}
.work-image img{display:block;width:100%;height:100%;object-fit:cover}
.work-copy>p:first-child{font-size:clamp(24px,2.5vw,38px);letter-spacing:-.035em;line-height:1.2;margin:0 0 28px;max-width:13ch}
#detail{margin:24px 0 0;max-width:28ch}
button:focus-visible{outline:3px solid var(--accent);outline-offset:4px}
/* Progressive enhancement: content stays visible without scripting or observers. */
@media (prefers-reduced-motion:no-preference){
  [data-reveal].reveal-ready{opacity:0;transform:translateY(22px)}
  [data-reveal].reveal-ready.is-visible{opacity:1;transform:none;transition:opacity 650ms ease,transform 650ms cubic-bezier(.22,1,.36,1);transition-delay:var(--reveal-delay,0ms)}
  [data-reveal]:focus-within{opacity:1"'!important;transform:none!important;transition:none!important}
}
@media(min-width:1664px){header{margin-inline:auto;max-width:1536px}}
@media(max-width:900px){
  #intro{gap:32px;grid-template-columns:minmax(0,1fr) minmax(0,.9fr)}
  h1{font-size:clamp(48px,7vw,66px)}
  .hero-media{min-height:500px}
  .work-layout{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:32px}
}
@media(max-width:640px){
  header{margin-inline:20px;padding-block:22px;gap:20px}
  header span{font-size:12px;letter-spacing:.1em}
  header a{font-size:13px}
  section{padding:40px 20px}
  #intro{grid-template-columns:1fr;gap:36px}
  .intro-copy{padding:0}
  .eyebrow{margin-bottom:26px;font-size:11px}
  h1{font-size:clamp(48px,11vw,70px);max-width:10ch;margin-bottom:24px}
  .intro-description{margin-bottom:28px}
  .hero-media{min-height:0;aspect-ratio:16/11}
  .hero-media::before{height:12px}
  #work{margin:8px 20px 0;padding-block:32px 48px}
  h2{margin-bottom:28px}
  .work-layout{grid-template-columns:1fr;gap:28px}
  .work-image{aspect-ratio:16/9}
  .work-copy>p:first-child{max-width:none;margin-bottom:20px}
}
@media(prefers-reduced-motion:reduce){
  [data-reveal]{opacity:1!important;transform:none!important;transition:none!important}
}
</style>
</head>
<body>
<header><span>FIELD NOTES</span> <a href="#work">Work</a> <a href="mailto:studio@example.test">Contact</a></header>
<main>
<section id="intro">
  <div class="intro-copy" data-reveal>
    <p class="eyebrow">INDEPENDENT FILM / 2026</p>
    <h1>Make room for the moving world.</h1>
    <p class="intro-description">Thoughtful films, clear stories, lasting places.</p>
    <a class="cta" id="explore" href="#work" data-track="explore">Explore the work</a>
  </div>
  <div class="hero-media" data-reveal style="--reveal-delay:120ms">
    <video muted playsinline loop controls preload="none" poster="assets/poster.svg" aria-label="Tidal study / 2026">
      <source src="assets/scene.webm" type="video/webm">
    </video>
  </div>
</section>
<section id="work">
  <h2 data-reveal>Selected work</h2>
  <div class="work-layout">
    <figure class="work-image" data-reveal>
      <img src="assets/poster.svg" alt="" width="960" height="540" loading="lazy" decoding="async">
    </figure>
    <div class="work-copy" data-reveal style="--reveal-delay:100ms">
      <p>Tidal study / 2026</p>
      <button id="details" type="button">Show details</button>
      <p id="detail" hidden>Filmed on the northern coast.</p>
    </div>
  </div>
</section>
</main>
<script>window.analytics=[];document.querySelector('"'[data-track]').addEventListener('click',()=>window.analytics.push('explore'));document.querySelector('#details').addEventListener('click',()=>{document.querySelector('#detail').hidden="'!document.querySelector('"'#detail').hidden});</script>
<script>
(() => {
  const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const video = document.querySelector('video');
  const reveals = document.querySelectorAll('[data-reveal]');
  let started = false;
  let revealObserver;

  const showAll = () => {
    if (revealObserver) revealObserver.disconnect();
    reveals.forEach(el => el.classList.remove('reveal-ready'));
  };

  if ("'!motion.matches && '"'IntersectionObserver' in window) {
    revealObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if ("'!entry.isIntersecting) return;
        entry.target.classList.add('"'is-visible');
        revealObserver.unobserve(entry.target);
      });
    }, { threshold: 0.12 });
    reveals.forEach(el => {
      el.classList.add('reveal-ready');
      revealObserver.observe(el);
    });
  }

  // Native controls remain available; automatic playback starts only once.
  // A user's pause is never undone by re-entering the viewport.
  if ('IntersectionObserver' in window) {
    const mediaObserver = new IntersectionObserver(entries => {
      const visible = entries[0].isIntersecting;
      if ("'!visible) video.pause();
      else if (!started && !motion.matches && !document.hidden) {
        started = true;
        video.muted = true;
        const playback = video.play();
        if (playback) playback.catch(() => {});
      }
    }, { threshold: 0.2 });
    mediaObserver.observe(video);
  }

  motion.addEventListener('"'change', () => {
    if (motion.matches) {
      video.pause();
      showAll();
    }
  });
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) video.pause();
  });
  video.addEventListener('error', () => {
    // Preserve the local poster if the browser cannot decode the footage.
    video.style.background = 'var(--ink) url(\"assets/poster.svg\") center / cover';
  });
})();
</script>
</body>
</html>
EOF"

