  const video = document.querySelector('video');
  const reveals = document.querySelectorAll('[data-reveal]');
  let started = false;
  let revealObserver;

  const showAll = () => {
    if (revealObserver) revealObserver.disconnect();
    reveals.forEach(el => el.classList.remove('reveal-ready'));
  };

  if (!motion.matches && 'IntersectionObserver' in window) {
    revealObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add('is-visible');
        revealObserver.unobserve(entry.target);
      });
    }, { threshold: 0.12 });
    reveals.forEach(el => {
      el.classList.add('reveal-ready');
      revealObserver.observe(el);
    });
  }

  // Native controls remain available; automatic playback starts only once.
  // A user's pause is never undone by re-entering the viewport.
  if ('IntersectionObserver' in window) {
    const mediaObserver = new IntersectionObserver(entries => {
      const visible = entries[0].isIntersecting;
      if (!visible) video.pause();
      else if (!started && !motion.matches && !document.hidden) {
        started = true;
        video.muted = true;
        const playback = video.play();
        if (playback) playback.catch(() => {});
      }
    }, { threshold: 0.2 });
    mediaObserver.observe(video);
  }

  motion.addEventListener('change', () => {
    if (motion.matches) {
      video.pause();
      showAll();
    }
  });
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) video.pause();
  });
  video.addEventListener('error', () => {
    // Preserve the local poster if the browser cannot decode the footage.
    video.style.background = 'var(--ink) url("assets/poster.svg") center / cover';
  });
})();
</script>
</body>
</html>
EOF

